int send_messages(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    struct msghdr msg = {0};
    size_t total_bytes_sent = 0;
    ssize_t bytes;
    int flags = MSG_NOSIGNAL;

    msg.msg_iov = iov;
    msg.msg_iovlen = n_vec;

    while (total_bytes_sent < iov[0].iov_len) {
        bytes = kernel_sendmsg(server->socket, &msg, flags);
        if (bytes < 0) {
            if (bytes == -EAGAIN || bytes == -EWOULDBLOCK) {
                // Non-blocking send would block, retry
                continue;
            } else if (bytes == -EPIPE) {
                // Connection closed by the remote side
                return -EPIPE;
            } else {
                // Some other error
                return bytes;
            }
        } else if (bytes == 0) {
            // No bytes sent, could be a timeout or other condition
            return -EAGAIN;
        }

        total_bytes_sent += bytes;
    }

    if (sent)
        *sent = total_bytes_sent;

    return total_bytes_sent;
}

int sendmsg_to_tcp_server(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    int ret = 0;
    size_t total_sent = 0;
    size_t i = 0;

    while (i < n_vec && iov[i].iov_len > 0) {
        ssize_t bytes = writev(server->sock, iov + i, n_vec - i);
        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            ret = -errno;
            break;
        } else if (bytes == 0) {
            ret = -ECONNRESET;
            break;
        }

        total_sent += bytes;
        while (i < n_vec && iov[i].iov_len <= bytes) {
            bytes -= iov[i].iov_len;
            i++;
        }

        if (i < n_vec) {
            iov[i].iov_base = (char *)iov[i].iov_base + bytes;
            iov[i].iov_len -= bytes;
        }
    }

    if (sent) {
        *sent = total_sent;
    }

    return (ret) ? ret : (int)total_sent;
}

int send_tcp_messages(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    struct msghdr msg = {0};
    size_t total_sent = 0;
    int ret;

    msg.msg_iov = iov;
    msg.msg_iovlen = n_vec;

    do {
        ret = kernel_sendmsg(server->socket, &msg, total_sent, iov, n_vec);
        if (ret < 0) {
            if (ret == -EAGAIN || ret == -EWOULDBLOCK) {
                continue; /* Retry in non-blocking case */
            }
            return ret;
        }

        total_sent += ret;

        if (total_sent < msg.msg_iov->iov_len) {
            msg.msg_iov->iov_base = (char *)msg.msg_iov->iov_base + ret;
            msg.msg_iov->iov_len -= ret;
        } else {
            msg.msg_iov++;
            msg.msg_iovlen--;
        }
    } while (msg.msg_iovlen > 0 && (ret > 0));

    if (sent)
        *sent = total_sent;

    return total_sent;
}

int sendmsg_to_tcp_server(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    struct msghdr msg = {0};
    int i, iov_idx = 0;
    size_t total_bytes_sent = 0;
    ssize_t bytes;

    msg.msg_iov = (struct iovec *)iov;
    msg.msg_iovlen = n_vec;

    while (iov_idx < n_vec) {
        bytes = sendmsg(server->socket, &msg, 0);
        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            return -errno;
        }
        total_bytes_sent += bytes;
        *sent = total_bytes_sent;

        for (i = 0; i < n_vec - iov_idx; i++) {
            if (iov[iov_idx + i].iov_len <= bytes) {
                bytes -= iov[iov_idx + i].iov_len;
                iov_idx += i + 1;
                break;
            } else {
                iov[iov_idx + i].iov_len -= bytes;
                iov[iov_idx + i].iov_base = (char *)iov[iov_idx + i].iov_base + bytes;
                break;
            }
        }

        if (i == n_vec - iov_idx) {
            iov_idx += i;
        }
    }

    return total_bytes_sent;
}

int send_tcp_messages(struct TCP_Server_Info *server, struct kvec *iov, size_t n_vec, size_t *sent) {
    size_t total_sent = 0;
    int ret = 0;
    struct msghdr msg;
    struct iovec *iov_copy = NULL;
    size_t i;

    iov_copy = kmalloc_array(n_vec, sizeof(struct iovec), GFP_KERNEL);
    if (!iov_copy)
        return -ENOMEM;

    for (i = 0; i < n_vec; ++i) {
        iov_copy[i].iov_base = iov[i].iov_base;
        iov_copy[i].iov_len = iov[i].iov_len;
    }

    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_iov = iov_copy;
    msg.msg_iovlen = n_vec;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;

    do {
        ret = kernel_sendmsg(server->sock, &msg, 0, iov_copy->iov_len, 0);
        if (ret < 0)
            break;

        total_sent += ret;
        iov_copy = iov_copy->iov_base + ret;
        --n_vec;
        iov_copy += 1;
    } while (n_vec > 0 && ret > 0);

    kfree(iov_copy);
    *sent = total_sent;
    return ret < 0 ? ret : total_sent;
}
